  git(['clone', '-q', origin, seed], cwd: root.path);
  git(['config', 'user.email', 't@t']);
  git(['config', 'user.name', 't']);
  Directory('$seed/flutter_app').createSync();
  File('$seed/pubspec.yaml').writeAsStringSync('version: 0.1.495\n');
  File(
