    for (final e in Platform.environment.entries)
      if (!e.key.startsWith('GIT_')) e.key: e.value,
    'PATH': '$bin:${Platform.environment['PATH']}',
    'FA_REAL_GIT': realGit,
    'FA_RACER': racer,
