    'bash',
    ['${Directory.current.path}/scripts/auto_release.sh'],
    workingDirectory: seed,
    environment: env,
    includeParentEnvironment: false, // sanitized above — no GIT_* leak
  );
  return AutoReleaseRun(
    res.exitCode,
    '${res.stdout}${res.stderr}',
    headBefore,
    originMain(),
    realGit,
    seed,
    origin,
    baseEnv,
  );
}

